ValidationRule.errorConditionFormula:
AND(
  NOT(ISCHANGED(Process_Technical_Field__c)),
  NOT(ISPICKVAL(Status__c, 'Rejected')),
  NOT(ISPICKVAL(Status__c, 'New')),

  /* Bloquer sauf si le champ modifié est uniquement Status__c et qu'on passe à "Sent" */
  NOT(
    AND(
      ISPICKVAL(Status__c, 'Sent'),
      ISCHANGED(Status__c)
    )
  ),

  /* Bloquer sauf si le champ modifié est uniquement Status__c et qu'on passe à "Approved" avec un approbateur */
  NOT(
    AND(
      ISPICKVAL(Status__c, 'Approved'),
      ISCHANGED(Status__c),
      OR(
        $User.Id = Approver__c,
        $User.Id = Approver_2__c
      )
    )
  ),

  /* Bloquer sauf si l'utilisateur est un approbateur et le statut est "Sent" */
  NOT(
    AND(
      ISPICKVAL(Status__c, 'Sent'),
      OR(
        $User.Id = Approver__c,
        $User.Id = Approver_2__c
      )
    )
  ),

  /* Bloquer toute modification si le statut est "Approved" */
  ISPICKVAL(Status__c, 'Approved')
)
